from math import log

def mm(a,b):
    return [[sum(x*y for x,y in zip(row,col)) for col in zip(*b)] for row in a]
def H(a):
    return -sum(x*log(x) for row in a for x in row if x>0)
for P in [[[.1,.9],[.01,.99]], [[.55,.45],[.005,.995]]]:
    nu=[1.,90.]
    xi=[sum(P[j][i]*nu[j] for j in range(2)) for i in range(2)]
    R=[[(nu[i]*P[i][j]+nu[j]*P[j][i])/(nu[i]+xi[i]) for j in range(2)] for i in range(2)]
    print('P=',P,'P_nu=',R)
    print('H(1),H(2),H(3),H(infty)=',H(R),H(mm(R,R)),H(mm(mm(R,R),R)),2*H([[x/sum(nu) for x in nu]]))
